/**
 * Typed handler-frame ABI for DEFINE'd message-bus handlers (backlog item 3).
 *
 * Frame layout (bottom → top at entry after caller band seeding):
 *   arguments | route context | journals | cursors | results
 *
 * Helpers declare stack-effect signatures; validateHandlerFrame proves entry/exit
 * shape agreement and rejects live anonymous / untracked cells at settlement.
 */

export type FrameSlotKind =
  | 'argument'
  | 'routeContext'
  | 'journal'
  | 'cursor'
  | 'result'
  | 'trackedTemp';

export interface FrameSlot {
  name: string;
  kind: FrameSlotKind;
}

export interface HandlerFrameSchema {
  handlerId: string;
  handlerName?: string;
  slots: readonly FrameSlot[];
}

/** Net stack delta: positive = pushes, negative = pops. */
export interface StackEffectSignature {
  helperId: string;
  /** Named slots consumed from the frame (must exist). */
  reads?: readonly string[];
  /** Named slots written/replaced. */
  writes?: readonly string[];
  /** Anonymous / untracked cells pushed (must be zero at settlement). */
  anonymousPushes?: number;
  /** Anonymous cells popped. */
  anonymousPops?: number;
  /** Alt-stack net delta (must return to 0 at settlement). */
  altStackDelta?: number;
}

export interface FrameValidationFailure {
  invariantId: string;
  detail: string;
  slot?: string;
}

export interface FrameValidationResult {
  ok: boolean;
  failures: readonly FrameValidationFailure[];
  /** Live anonymous cell count after applying effects. */
  anonymousLive: number;
  altStackDepth: number;
}

export function buildHandlerFrameSchema(params: {
  handlerId: string;
  handlerName?: string;
  arguments: readonly string[];
  routeContext?: readonly string[];
  journals?: readonly string[];
  cursors?: readonly string[];
  results?: readonly string[];
}): HandlerFrameSchema {
  const slots: FrameSlot[] = [
    ...params.arguments.map((name) => ({ name, kind: 'argument' as const })),
    ...(params.routeContext ?? []).map((name) => ({ name, kind: 'routeContext' as const })),
    ...(params.journals ?? []).map((name) => ({ name, kind: 'journal' as const })),
    ...(params.cursors ?? []).map((name) => ({ name, kind: 'cursor' as const })),
    ...(params.results ?? []).map((name) => ({ name, kind: 'result' as const })),
  ];
  return {
    handlerId: params.handlerId,
    handlerName: params.handlerName,
    slots,
  };
}

/**
 * Symbolically apply stack-effect signatures against a frame schema.
 * Fails closed on unknown slot reads/writes, leftover anonymous cells, or alt-stack imbalance.
 */
export function validateHandlerFrame(
  schema: HandlerFrameSchema,
  effects: readonly StackEffectSignature[],
): FrameValidationResult {
  const known = new Set(schema.slots.map((slot) => slot.name));
  const failures: FrameValidationFailure[] = [];
  let anonymousLive = 0;
  let altStackDepth = 0;

  for (const effect of effects) {
    for (const name of effect.reads ?? []) {
      if (!known.has(name)) {
        failures.push({
          invariantId: 'unknown-frame-read',
          detail: `helper ${effect.helperId} reads unknown slot`,
          slot: name,
        });
      }
    }
    for (const name of effect.writes ?? []) {
      if (!known.has(name)) {
        failures.push({
          invariantId: 'unknown-frame-write',
          detail: `helper ${effect.helperId} writes unknown slot`,
          slot: name,
        });
      }
    }
    anonymousLive += effect.anonymousPushes ?? 0;
    anonymousLive -= effect.anonymousPops ?? 0;
    if (anonymousLive < 0) {
      failures.push({
        invariantId: 'anonymous-underflow',
        detail: `helper ${effect.helperId} popped more anonymous cells than live`,
      });
      anonymousLive = 0;
    }
    altStackDepth += effect.altStackDelta ?? 0;
    if (altStackDepth < 0) {
      failures.push({
        invariantId: 'alt-stack-underflow',
        detail: `helper ${effect.helperId} unbalanced alt-stack`,
      });
      altStackDepth = 0;
    }
  }

  if (anonymousLive !== 0) {
    failures.push({
      invariantId: 'live-anonymous-at-settlement',
      detail: `settlement leaves ${anonymousLive} anonymous cell(s); top/bottom bookkeeping drift`,
    });
  }
  if (altStackDepth !== 0) {
    failures.push({
      invariantId: 'alt-stack-imbalance',
      detail: `settlement alt-stack depth ${altStackDepth}`,
    });
  }

  return {
    ok: failures.length === 0,
    failures,
    anonymousLive,
    altStackDepth,
  };
}
